import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import { useState, useEffect } from 'react';
import axios from 'axios';
import Button from '@mui/material/Button';
import { Link } from 'react-router-dom'; 

export default function ViewCategory() {
  const [category, setCategory] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:7000/category/getCategory") 
      .then((res) => {
        console.log(res.data.data);
        setCategory(res.data.data);  {/* ← Fix to data */}
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const HandleDelete = (id) => {
    axios.delete(`http://localhost:7000/category/deleteCategoryById/${id}`) 
      .then((res) => {
        console.log(res);
        alert("Category deleted");
        setCategory(category.filter((item) => item._id !== id));  
      })
      .catch((error) => {
        console.log(error);
      });
  };

  return (
    <div>
      <h2>Category</h2>
      <TableContainer component={Paper}>
        <Table>

          <TableHead>
            <TableRow>
              <TableCell align="right">Category Name</TableCell>  
              <TableCell align="right">Description</TableCell>
              <TableCell align="right">Action</TableCell>
            </TableRow>
          </TableHead>

          <TableBody>
            {category.map((row) => (
              <TableRow key={row._id}>
                <TableCell align="right">{row.categoryName}</TableCell>  
                <TableCell align="right">{row.description}</TableCell>

                <TableCell align="right">
                  <Button
                    variant='outlined'
                    component={Link}
                    to={`/Admin/UpdateCategory/${row._id}`}  
                  >
                    UPDATE
                  </Button>

                  <Button
                    variant='outlined'
                    onClick={() => HandleDelete(row._id)}
                    style={{ marginLeft: "10px" }}
                  >
                    DELETE
                  </Button>
                </TableCell>

              </TableRow>
            ))}
          </TableBody>

        </Table>
      </TableContainer>
    </div>
  );
}